def to_paise(text):
    if '.' in text:
        rupees, frac = text.split('.')
        frac = (frac + '00')[:2]
    else:
        rupees, frac = text, '00'
    return int(rupees or '0') * 100 + int(frac)

def money(paise):
    return f'{paise // 100}.{paise % 100:02d}'

n = int(input())
total = 0
for _ in range(n):
    name, qty, price = input().split()
    qty = int(qty)
    amount = qty * to_paise(price)
    total += amount
    label = name.replace('_', ' ').title()
    print(f'{label:<14}{qty:>4}{money(amount):>10}')
print(f"{'TOTAL':<18}{money(total):>10}")
